					if refused.Data["code"] != "EVENT_REPLAY_NO_DELIVERY_HISTORY" || lifecycleStoredSnapshot(t, rt.ReceiverStateReader, seed.RunID) != snapshot {
						t.Fatal("node-only public refusal contract changed")
					}
